import sys

def factorial(n):
    # 调整递归深度限制，至少为 n+10，同时确保不低于默认值
    limit = max(n + 10, 1000)
    sys.setrecursionlimit(limit)

    def fact(x):
        if x == 0:
            return 1
        return x * fact(x - 1)

    try:
        return fact(n)
    except RecursionError:
        print('递归深度过大')
        return None
